import numpy as np

def initialize(distances, demands, coords, capacity):
    n = len(demands)
    heuristic = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            if i != j:
                distance = distances[i, j] if distances[i, j] > 0 else 1e-10
                if demands[j] <= capacity:
                    normalized_demand = demands[j] / capacity
                    capacity_pressure = (1 - normalized_demand) ** 2 # Squared term for stronger pressure
                    heuristic[i, j] = capacity_pressure / distance
    pheromone = np.ones((n, n))
    return heuristic, pheromone

